"""Build the review page with the edit, voice auditions and reusable cast footage."""
from pathlib import Path
import sys,shutil,json
root=Path(sys.argv[1]);repo=Path(__file__).resolve().parents[4];assets=root/'assets'
shutil.copy2(repo/'public/home-2/fonts/tt-hoves-regular.ttf',assets/'hoves.ttf')
cast=[('People & Culture','people','', 'Listening and blinking; no instrument assigned.'),('Operations','drums','drums-playing','Drum pad and sticks.'),('Kevin · Partnerships','guitar','guitar-playing','Guitar, wider framing.'),('Keys · Enablement','keys-full','keys-full-playing','Keyboard, wider framing.'),('Strategy','strategy','','City skyline virtual backdrop.'),('Arjun · Finance','arjun','','Listening and restrained reactions.'),('Linda · Governance','linda','','Listening and restrained reactions.')]
cards=[]
for name,stem,instrument,desc in cast:
 variants=[('Listening',stem+'-listening'),('Speaking study',stem+'-speaking')]
 if instrument:variants.append(('Instrument',instrument))
 for _,src in variants:shutil.copy2(repo/f'public/studio/season/clips/{src}.mp4',assets/f'{src}.mp4')
 choices=''.join(f'<button type="button" data-src="assets/{src}.mp4" aria-pressed="{str(i==0).lower()}">{label}</button>' for i,(label,src) in enumerate(variants))
 cards.append(f'<article><video controls muted playsinline preload="metadata" src="assets/{variants[0][1]}.mp4"></video><div class="pad"><h3>{name}</h3><p>{desc}</p><div class="choices">{choices}</div></div></article>')
voices=[('A · Young, lightly robotic','voice-brodie.wav','A youthful delivery with a light electronic texture; no added echo.'),('B · More machine','voice-xylar.wav','A modulated character voice, with no additional echo.'),('Current Synergy','voice-current-levelled.wav','The established voice used in the episode above.')]
audios=''.join(f'<article class="pad"><h3>{name}</h3><p>{desc}</p><audio controls preload="metadata" src="assets/{file}"></audio></article>' for name,file,desc in voices)
coffees=''.join(f'<article><video controls muted playsinline preload="metadata" src="assets/coffee-{i}.mp4"></video><div class="pad"><h3>Coffee take {j+1}</h3></div></article>' for j,i in enumerate([0,1,2,3,5,6]))
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>A more intentional first day · LinkedIn Beats</title><style>
@font-face{font-family:Hoves;src:url('assets/hoves.ttf')}*{box-sizing:border-box}body{margin:0;background:#f2efe6;color:#112e43;font:18px Hoves,Arial,sans-serif}main{max-width:1280px;margin:auto;padding:36px 28px 72px}h1{font-size:clamp(32px,4.5vw,60px);font-weight:500;letter-spacing:-.04em;margin:14px 0 18px}h2{font-size:32px;font-weight:500;margin:48px 0 18px}h3{font-size:22px;font-weight:500;margin:0 0 10px}p{line-height:1.5;max-width:820px;margin:0 0 20px}a{color:#1654ad;text-underline-offset:4px}video{display:block;width:100%;background:#102a3d;border-radius:22px}#episode{aspect-ratio:16/9}article{background:white;border-radius:22px;overflow:hidden}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.voices{grid-template-columns:repeat(3,1fr)}.pad{padding:24px}article p{font-size:16px}.pad p{min-height:48px}audio{width:100%}.choices{display:flex;gap:8px;flex-wrap:wrap}button{font:16px Hoves;padding:10px 14px;border:1px solid #cad3d8;border-radius:24px;background:#fff;color:#12364d;cursor:pointer}button[aria-pressed=true]{background:#1552c1;color:white;border-color:#1552c1}button:focus-visible,a:focus-visible{outline:3px solid #1552c1;outline-offset:4px}.links{margin:20px 0 0}summary{font-size:24px;cursor:pointer;margin:24px 0}footer{margin-top:48px;font-size:16px}@media(max-width:760px){main{padding:24px 16px}.grid,.voices{grid-template-columns:1fr}.pad{padding:20px}}
</style><main><a href="../photo/">Compare previous cut</a><h1>A more intentional first day.</h1><p>Fast paper titles. Real reactions. A brief coffee break.</p><video id="episode" controls playsinline preload="metadata" poster="output/frames/review-5.png" src="output/chatgpt-meeting-photo-v4.mp4"><track kind="captions" label="English" srclang="en" src="output/captions.vtt"></video><p class="links"><a href="output/chatgpt-meeting-photo-v4.mp4" download>Download the 90-second cut</a> · <a href="#voices">Compare Synergy voices</a> · <a href="#cast">Cast footage</a></p><h2 id="voices">Synergy voice auditions</h2><p>The same three lines in each sample, level-matched for comparison. The episode retains the current voice and music while we choose his next voice.</p><div class="grid voices">__VOICES__</div><h2 id="cast">The reusable cast</h2><p>Existing listening and speaking performances, plus wider instrument views where those roles are established. These are performance references, not newly lip-synced dialogue. Strategy’s city skyline supplies the virtual-background direction.</p><div class="grid">__CAST__</div><details><summary>Synergy’s coffee takes · six unique clips</summary><div class="grid">__COFFEE__</div></details><footer>linkedinbeats.com · Not affiliated with LinkedIn.<br>A project by Aaron Phelps at Look-Serious.com</footer></main><script>
document.querySelectorAll('.choices button').forEach(b=>b.addEventListener('click',()=>{let card=b.closest('article'),v=card.querySelector('video');v.pause();v.src=b.dataset.src;card.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));v.play().catch(()=>{})}));document.querySelectorAll('audio,video').forEach(m=>m.addEventListener('play',()=>document.querySelectorAll('audio,video').forEach(other=>{if(other!==m)other.pause()})));
</script></html>'''.replace('__VOICES__',audios).replace('__CAST__',''.join(cards)).replace('__COFFEE__',coffees)
(root/'index.html').write_text(html)
print('Review page saved')
